BarChartProps.text:
export interface BarChartProps extends ChartCardProps {
    categories: string[];
    series: TrendSeries[];
    direction?: 'vertical' | 'horizontal';
    stacked?: boolean;
}

ChartCardProps.text:
export interface ChartCardProps {
    title?: string;
    subtitle?: string;
    height?: string | number;
    loading?: boolean;
    empty?: boolean;
    emptyText?: string;
}

ChartCardSlots.text:
export interface ChartCardSlots {
    extra?: () => VNodeChild;
    default?: () => VNodeChild;
}

PieChartProps.text:
export interface PieChartProps extends ChartCardProps {
    data: PieDatum[];
    innerRadius?: number;
    centerLabel?: string;
    centerValue?: string | number;
}

PieDatum.text:
export interface PieDatum {
    name: string;
    value: number;
    color?: string;
}

RankItem.text:
export interface RankItem {
    name: string;
    value: number;
    color?: string;
}

RankListProps.text:
export interface RankListProps {
    data: RankItem[];
    max?: number;
    formatter?: (value: number) => string;
    limit?: number;
}

StatCardProps.text:
export interface StatCardProps {
    title: string;
    value: number | string;
    prefix?: string;
    suffix?: string;
    precision?: number;
    change?: number | null;
    changeTone?: ChangeTone;
    changeLabel?: string;
    trend?: number[];
    loading?: boolean;
    clickable?: boolean;
}

StatCardSlots.text:
export interface StatCardSlots {
    icon?: () => VNodeChild;
    footer?: () => VNodeChild;
}

StatGroupProps.text:
export interface StatGroupProps {
    columns?: number | {
        xs?: number;
        sm?: number;
        md?: number;
        lg?: number;
    };
    gap?: 'sm' | 'md' | 'lg';
}

TrendChartProps.text:
export interface TrendChartProps extends ChartCardProps {
    categories: string[];
    series: TrendSeries[];
    area?: boolean;
    smooth?: boolean;
    startFromZero?: boolean;
}

TrendSeries.text:
export interface TrendSeries {
    name: string;
    data: number[];
    color?: string;
}
